1	package zkcircuit
2	
3	import (
4		"sort"
5		"strings"
6	)
7	
8	// This file holds the domain operations of the persistent workbench. Every
9	// mutating operation validates its request before touching state, runs under
10	// the shared process lock and either commits one complete new state or
11	// commits nothing.
12	
13	// CreateCircuit creates a draft circuit version identified by Name+Version.
14	//
15	// The name must be non-empty and not only whitespace; Version must be
16	// positive; Constraints must be positive; the input counts must not be
17	// negative. Creating an already-existing version is idempotent when the
18	// description is identical (the stored record is returned unchanged); a
19	// differing description is reported as ErrConflict. Nothing about an
20	// existing version — frozen or not — is ever replaced by Create.
21	func (s *Store) CreateCircuit(c Circuit) (Circuit, error) {
22		if err := validateCircuitKey(c.Name, c.Version); err != nil {
23			return Circuit{}, err
24		}
25		if err := validateCounts(c.Constraints, c.PublicInputs, c.PrivateInputs); err != nil {
26			return Circuit{}, err
27		}
28	
29		var result Circuit
30		err := s.withLock(func() (bool, error) {
31			if existing := findCircuit(s.data.Circuits, c.Name, c.Version); existing != nil {
32				if existing.Description != c.Description {
33					return false, conflictf("circuit %q version %d already exists with a different description", c.Name, c.Version)
34				}
35				result = circuitFromPersist(*existing)
36				return false, nil
37			}
38			record := persistCircuit{
39				Name: c.Name, Version: c.Version,
40				Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
41				Frozen: false, Description: c.Description,
42			}
43			s.data.Circuits = append(s.data.Circuits, record)
44			result = circuitFromPersist(record)
45			return true, nil
46		})
47		return result, err
48	}
49	
50	// UpdateCircuit modifies a draft circuit version. It must target an existing,
51	// unfrozen version explicitly: unknown versions yield ErrNotFound and frozen
52	// versions yield ErrFrozen. On success the counts and description are
53	// replaced as one atomic change; partial updates can never be observed.
54	func (s *Store) UpdateCircuit(c Circuit) (Circuit, error) {
55		if err := validateCircuitKey(c.Name, c.Version); err != nil {
56			return Circuit{}, err
57		}
58		if err := validateCounts(c.Constraints, c.PublicInputs, c.PrivateInputs); err != nil {
59			return Circuit{}, err
60		}
61	
62		var result Circuit
63		err := s.withLock(func() (bool, error) {
64			existing := findCircuit(s.data.Circuits, c.Name, c.Version)
65			if existing == nil {
66				return false, notFoundf("circuit %q version %d does not exist", c.Name, c.Version)
67			}
68			if existing.Frozen {
69				return false, frozenf("circuit %q version %d is frozen and its description cannot be modified", c.Name, c.Version)
70			}
71			// When a definition is already imported, changing the three counts is
72			// only accepted as a whole if the definition stays legal under them
73			// (exact constraint count, all wires inside the new input layout).
74			if existing.Definition != nil {
75				parsed, perr := definitionFromPersist(*existing.Definition, existing.PublicInputs, existing.PrivateInputs)
76				if perr != nil {
77					return false, corruptf("stored definition for %q v%d is unreadable: %v", c.Name, c.Version, perr)
78				}
79				if !parsed.compatibleWith(c.Constraints, c.PublicInputs, c.PrivateInputs) {
80					return false, invalidf("update rejected: it would make the imported constraint definition illegal (constraint count or wire layout mismatch); the whole change is refused")
81				}
82			}
83			existing.Constraints = c.Constraints
84			existing.PublicInputs = c.PublicInputs
85			existing.PrivateInputs = c.PrivateInputs
86			existing.Description = c.Description
87			result = circuitFromPersist(*existing)
88			return true, nil
89		})
90		return result, err
91	}
92	
93	// PartialCircuit carries optional replacement fields for one draft circuit
94	// version. A nil pointer leaves the stored field untouched; a non-nil pointer
95	// — even to zero or to the empty string — replaces the field. This lets a
96	// caller change exactly one field without restating the others.
97	type PartialCircuit struct {
98		Constraints   *int
99		PublicInputs  *int
100		PrivateInputs *int
101		Description   *string
102	}
103	
104	// UpdateCircuitPartial modifies selected fields of a draft circuit version.
105	//
106	// Only fields present in patch are changed; omitted fields keep their stored
107	// values. The whole merged result is validated before anything is committed:
108	// constraints must stay positive and input counts non-negative, and when a
109	// constraint definition is already imported the merged counts must keep it
110	// legal (exact constraint count, every referenced wire inside the new input
111	// layout). Any rejected field refuses the entire change — description,
112	// counts and the stored definition all remain as they were.
113	//
114	// Unknown versions yield ErrNotFound and frozen versions ErrFrozen even when
115	// no field is being changed. A patch that provides no modifiable field at
116	// all returns the stored record unchanged and commits nothing (no new
117	// version, no data write).
118	func (s *Store) UpdateCircuitPartial(name string, version int, patch PartialCircuit) (Circuit, error) {
119		if err := validateCircuitKey(name, version); err != nil {
120			return Circuit{}, err
121		}
122	
123		var result Circuit
124		err := s.withLock(func() (bool, error) {
125			existing := findCircuit(s.data.Circuits, name, version)
126			if existing == nil {
127				return false, notFoundf("circuit %q version %d does not exist", name, version)
128			}
129			if existing.Frozen {
130				return false, frozenf("circuit %q version %d is frozen and cannot be modified", name, version)
131			}
132			// Merge the provided fields over the stored record; omitted fields
133			// keep their committed values.
134			merged := *existing
135			if patch.Constraints != nil {
136				merged.Constraints = *patch.Constraints
137			}
138			if patch.PublicInputs != nil {
139				merged.PublicInputs = *patch.PublicInputs
140			}
141			if patch.PrivateInputs != nil {
142				merged.PrivateInputs = *patch.PrivateInputs
143			}
144			if patch.Description != nil {
145				merged.Description = *patch.Description
146			}
147			if err := validateCounts(merged.Constraints, merged.PublicInputs, merged.PrivateInputs); err != nil {
148				return false, err
149			}
150			// When a definition is already imported, the merged counts must keep
151			// it legal (exact constraint count, all wires inside the new input
152			// layout). The definition itself is never touched here.
153			if existing.Definition != nil {
154				parsed, perr := definitionFromPersist(*existing.Definition, existing.PublicInputs, existing.PrivateInputs)
155				if perr != nil {
156					return false, corruptf("stored definition for %q v%d is unreadable: %v", name, version, perr)
157				}
158				if !parsed.compatibleWith(merged.Constraints, merged.PublicInputs, merged.PrivateInputs) {
159					return false, invalidf("update rejected: it would make the imported constraint definition illegal (constraint count or wire layout mismatch); the whole change is refused")
160				}
161			}
162			// No modifiable field was provided: return the stored record without
163			// committing anything.
164			if patch.Constraints == nil && patch.PublicInputs == nil && patch.PrivateInputs == nil && patch.Description == nil {
165				result = circuitFromPersist(*existing)
166				return false, nil
167			}
168			existing.Constraints = merged.Constraints
169			existing.PublicInputs = merged.PublicInputs
170			existing.PrivateInputs = merged.PrivateInputs
171			existing.Description = merged.Description
172			result = circuitFromPersist(*existing)
173			return true, nil
174		})
175		return result, err
176	}
177	
178	// FreezeCircuit freezes a circuit version. Unknown versions yield
179	// ErrNotFound. Freezing an already-frozen version returns that version
180	// unchanged (idempotent). Once frozen, name, version and the three counts
181	// can never change again.
182	func (s *Store) FreezeCircuit(name string, version int) (Circuit, error) {
183		if err := validateCircuitKey(name, version); err != nil {
184			return Circuit{}, err
185		}
186	
187		var result Circuit
188		err := s.withLock(func() (bool, error) {
189			existing := findCircuit(s.data.Circuits, name, version)
190			if existing == nil {
191				return false, notFoundf("circuit %q version %d does not exist", name, version)
192			}
193			if existing.Frozen {
194				result = circuitFromPersist(*existing)
195				return false, nil
196			}
197			existing.Frozen = true
198			result = circuitFromPersist(*existing)
199			return true, nil
200		})
201		return result, err
202	}
203	
204	// RecordSetup records a trusted setup for one frozen circuit version. The
205	// record belongs exclusively to that name+version. Unknown versions yield
206	// ErrNotFound; non-frozen versions yield ErrNotFrozen. Re-registering a
207	// setup for the same version is idempotent and adds no duplicate record.
208	func (s *Store) RecordSetup(name string, version int) (Setup, error) {
209		if err := validateCircuitKey(name, version); err != nil {
210			return Setup{}, err
211		}
212	
213		var result Setup
214		err := s.withLock(func() (bool, error) {
215			circuit := findCircuit(s.data.Circuits, name, version)
216			if circuit == nil {
217				return false, notFoundf("circuit %q version %d does not exist", name, version)
218			}
219			if !circuit.Frozen {
220				return false, notFrozenf("circuit %q version %d must be frozen before its trusted setup is recorded", name, version)
221			}
222			if existing := findSetup(s.data.Setups, name, version); existing != nil {
223				result = setupFromPersist(*existing)
224				return false, nil
225			}
226			record := persistSetup{Name: name, Version: version}
227			s.data.Setups = append(s.data.Setups, record)
228			result = setupFromPersist(record)
229			return true, nil
230		})
231		return result, err
232	}
233	
234	// SubmitJob accepts and stores a prove job. Only kind "prove" is accepted;
235	// no proving computation runs, the accepted request alone is persisted.
236	//
237	// The job id must be non-empty and not only whitespace, circuit name and
238	// version must be explicit and Attempt must be positive. Failure reasons are
239	// distinguishable: ErrNotFound (version unknown), ErrNotFrozen (version is
240	// still a draft) and ErrSetupMissing (no trusted setup for that version). A
241	// refused submission leaves no job behind.
242	//
243	// Resubmitting the same id with the same request returns the stored job;
244	// the same id with different content yields ErrConflict. A stored job stays
245	// pinned to the version submitted, regardless of circuit versions added
246	// later.
247	func (s *Store) SubmitJob(job Job) (Job, error) {
248		if strings.TrimSpace(job.ID) == "" {
249			return Job{}, invalidf("job id must be non-empty and not only whitespace")
250		}
251		if strings.TrimSpace(job.Circuit) == "" {
252			return Job{}, invalidf("job %q must name a circuit", job.ID)
253		}
254		if job.Version <= 0 {
255			return Job{}, invalidf("job %q must pin a positive circuit version", job.ID)
256		}
257		if job.Attempt <= 0 {
258			return Job{}, invalidf("job %q attempt must be a positive integer", job.ID)
259		}
260		if job.Kind != "prove" {
261			return Job{}, StoreError{Kind: ErrUnsupportedKind.Kind,
262				Detail: "job " + job.ID + " has unsupported kind " + job.Kind + "; only \"prove\" jobs are accepted"}
263		}
264	
265		var result Job
266		err := s.withLock(func() (bool, error) {
267			if existing := findJob(s.data.Jobs, job.ID); existing != nil {
268				if !sameJobRequest(*existing, job) {
269					return false, conflictf("job %q already exists with a different request", job.ID)
270				}
271				result = jobFromPersist(*existing)
272				return false, nil
273			}
274			circuit := findCircuit(s.data.Circuits, job.Circuit, job.Version)
275			if circuit == nil {
276				return false, notFoundf("job %q references unknown circuit %q version %d", job.ID, job.Circuit, job.Version)
277			}
278			if !circuit.Frozen {
279				return false, notFrozenf("job %q references circuit %q version %d which is not frozen", job.ID, job.Circuit, job.Version)
280			}
281			if findSetup(s.data.Setups, job.Circuit, job.Version) == nil {
282				return false, setupMissingf("job %q references frozen circuit %q version %d which has no recorded trusted setup",
283					job.ID, job.Circuit, job.Version)
284			}
285			record := persistJob{
286				ID: job.ID, Circuit: job.Circuit, Version: job.Version,
287				Kind: job.Kind, Attempt: job.Attempt, Artifact: job.Artifact,
288			}
289			s.data.Jobs = append(s.data.Jobs, record)
290			result = jobFromPersist(record)
291			return true, nil
292		})
293		return result, err
294	}
295	
296	// GetCircuit returns one circuit version, sorted-field populated exactly as
297	// stored. Unknown versions yield ErrNotFound.
298	func (s *Store) GetCircuit(name string, version int) (Circuit, error) {
299		if err := validateCircuitKey(name, version); err != nil {
300			return Circuit{}, err
301		}
302		var result Circuit
303		err := s.withLockRead(func() error {
304			existing := findCircuit(s.data.Circuits, name, version)
305			if existing == nil {
306				return notFoundf("circuit %q version %d does not exist", name, version)
307			}
308			result = circuitFromPersist(*existing)
309			return nil
310		})
311		return result, err
312	}
313	
314	// ListCircuits returns all stored circuit versions ordered by circuit name
315	// (lexicographically) and then by ascending version number.
316	func (s *Store) ListCircuits() ([]Circuit, error) {
317		var result []Circuit
318		err := s.withLockRead(func() error {
319			ordered := append([]persistCircuit(nil), s.data.Circuits...)
320			sort.Slice(ordered, func(i, j int) bool {
321				if ordered[i].Name != ordered[j].Name {
322					return ordered[i].Name < ordered[j].Name
323				}
324				return ordered[i].Version < ordered[j].Version
325			})
326			result = make([]Circuit, len(ordered))
327			for i, c := range ordered {
328				result[i] = circuitFromPersist(c)
329			}
330			return nil
331		})
332		return result, err
333	}
334	
335	// GetSetup reports whether a trusted setup is registered for the named
336	// frozen version. A missing record yields ErrNotFound.
337	func (s *Store) GetSetup(name string, version int) (Setup, bool, error) {
338		if err := validateCircuitKey(name, version); err != nil {
339			return Setup{}, false, err
340		}
341		var result Setup
342		found := false
343		err := s.withLockRead(func() error {
344			existing := findSetup(s.data.Setups, name, version)
345			if existing == nil {
346				return nil
347			}
348			result = setupFromPersist(*existing)
349			found = true
350			return nil
351		})
352		return result, found, err
353	}
354	
355	// GetJob returns one stored job by id. Unknown ids yield ErrNotFound.
356	func (s *Store) GetJob(id string) (Job, error) {
357		if strings.TrimSpace(id) == "" {
358			return Job{}, invalidf("job id must be non-empty and not only whitespace")
359		}
360		var result Job
361		err := s.withLockRead(func() error {
362			existing := findJob(s.data.Jobs, id)
363			if existing == nil {
364				return notFoundf("job %q does not exist", id)
365			}
366			result = jobFromPersist(*existing)
367			return nil
368		})
369		return result, err
370	}
371	
372	// ListJobs returns all accepted jobs ordered by job id lexicographically.
373	func (s *Store) ListJobs() ([]Job, error) {
374		var result []Job
375		err := s.withLockRead(func() error {
376			ordered := append([]persistJob(nil), s.data.Jobs...)
377			sort.Slice(ordered, func(i, j int) bool { return ordered[i].ID < ordered[j].ID })
378			result = make([]Job, len(ordered))
379			for i, j := range ordered {
380				result[i] = jobFromPersist(j)
381			}
382			return nil
383		})
384		return result, err
385	}
386	
387	// --- validation helpers ---------------------------------------------------
388	
389	func validateCircuitKey(name string, version int) error {
390		if strings.TrimSpace(name) == "" {
391			return invalidf("circuit name must be non-empty and not only whitespace")
392		}
393		if version <= 0 {
394			return invalidf("circuit %q version must be a positive integer, got %d", name, version)
395		}
396		return nil
397	}
398	
399	func validateCounts(constraints, publicInputs, privateInputs int) error {
400		if constraints <= 0 {
401			return invalidf("constraints must be greater than zero, got %d", constraints)
402		}
403		if publicInputs < 0 {
404			return invalidf("public input count must not be negative, got %d", publicInputs)
405		}
406		if privateInputs < 0 {
407			return invalidf("private input count must not be negative, got %d", privateInputs)
408		}
409		return nil
410	}
411	
412	// --- lookup / mapping helpers --------------------------------------------
413	
414	func findCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
415		for i := range cs {
416			if cs[i].Name == name && cs[i].Version == version {
417				return &cs[i]
418			}
419		}
420		return nil
421	}
422	
423	func findSetup(ps []persistSetup, name string, version int) *persistSetup {
424		for i := range ps {
425			if ps[i].Name == name && ps[i].Version == version {
426				return &ps[i]
427			}
428		}
429		return nil
430	}
431	
432	func findJob(js []persistJob, id string) *persistJob {
433		for i := range js {
434			if js[i].ID == id {
435				return &js[i]
436			}
437		}
438		return nil
439	}
440	
441	func sameJobRequest(stored persistJob, request Job) bool {
442		return stored.Circuit == request.Circuit &&
443			stored.Version == request.Version &&
444			stored.Kind == request.Kind &&
445			stored.Attempt == request.Attempt
446	}
447	
448	func circuitFromPersist(c persistCircuit) Circuit {
449		return Circuit{
450			Name: c.Name, Version: c.Version,
451			Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
452			Frozen: c.Frozen, Description: c.Description,
453		}
454	}
455	
456	func setupFromPersist(p persistSetup) Setup {
457		return Setup{Name: p.Name, Version: p.Version}
458	}
459	
460	func jobFromPersist(j persistJob) Job {
461		return Job{
462			ID: j.ID, Circuit: j.Circuit, Version: j.Version,
463			Kind: j.Kind, Attempt: j.Attempt, Artifact: j.Artifact,
464		}
465	}
466

