1	package zkcircuit
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11		"sync"
12	)
13	
14	// on-disk layout inside the data directory:
15	//
16	//	data.json    – the committed state (JSON envelope, atomically replaced)
17	//	data.json.tmp– staging file for the next commit (rename(2) target)
18	//	lock         – flock file serializing concurrent processes
19	//
20	// The envelope carries an explicit format version: files written by an
21	// incompatible future build are refused rather than silently migrated or
22	// overwritten.
23	const (
24		dirDataFile = "data.json"
25		dirTmpFile  = "data.json.tmp"
26		dirLockFile = "lock"
27	
28		// FormatVersion is the on-disk format this build writes and accepts.
29		FormatVersion = 1
30	)
31	
32	// envelope is the persisted state container.
33	type envelope struct {
34		Format    int               `json:"format"`
35		Circuits  []persistCircuit  `json:"circuits"`
36		Setups    []persistSetup    `json:"setups"`
37		Jobs      []persistJob      `json:"jobs"`
38		Artifacts []persistArtifact `json:"artifacts,omitempty"`
39	}
40	
41	type persistTerm struct {
42		Wire  int    `json:"wire"`
43		Coeff string `json:"coeff"`
44	}
45	
46	type persistConstraint struct {
47		A []persistTerm `json:"a"`
48		B []persistTerm `json:"b"`
49		C []persistTerm `json:"c"`
50	}
51	
52	// persistDefinition is the canonical, already-validated constraint set bound
53	// to one circuit version. The public/private partition is owned by the
54	// circuit record and is deliberately not duplicated here, so it can never
55	// drift from the declared counts.
56	type persistDefinition struct {
57		Modulus     string              `json:"modulus"`
58		Constraints []persistConstraint `json:"constraints"`
59	}
60	
61	// persistArtifact is a compiled artifact: the version's identity and
62	// constraint count bound to its recomputable SHA-256 hash.
63	type persistArtifact struct {
64		Name        string `json:"name"`
65		Version     int    `json:"version"`
66		Modulus     int64  `json:"modulus"`
67		Constraints int    `json:"constraints"`
68		Hash        string `json:"hash"`
69	}
70	
71	type persistCircuit struct {
72		Name          string             `json:"name"`
73		Version       int                `json:"version"`
74		Constraints   int                `json:"constraints"`
75		PublicInputs  int                `json:"public_inputs"`
76		PrivateInputs int                `json:"private_inputs"`
77		Frozen        bool               `json:"frozen"`
78		Description   string             `json:"description"`
79		Definition    *persistDefinition `json:"definition,omitempty"`
80	}
81	
82	type persistSetup struct {
83		Name    string `json:"name"`
84		Version int    `json:"version"`
85	}
86	
87	type persistJob struct {
88		ID       string `json:"id"`
89		Circuit  string `json:"circuit"`
90		Version  int    `json:"version"`
91		Kind     string `json:"kind"`
92		Attempt  int    `json:"attempt"`
93		Artifact string `json:"artifact,omitempty"`
94	}
95	
96	// Store is a persistent workbench backed by one local data directory.
97	//
98	// All operations are safe for concurrent use by multiple goroutines and by
99	// several processes pointed at the same directory: an in-process mutex plus a
100	// process-shared flock serialize commits, and every commit is an atomic
101	// temp-file/fsync/rename replacement. Open the directory with Open and call
102	// Close when done.
103	type Store struct {
104		dir  string
105		mu   sync.Mutex
106		lock *os.File
107	
108		data envelope
109	}
110	
111	// Open opens (creating if needed) the workbench data in dir. If the
112	// directory does not exist it is created. Existing committed data is loaded
113	// and fully validated before Open returns; on a corrupt, truncated or
114	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
115	// leaves every file in the directory untouched.
116	func Open(dir string) (*Store, error) {
117		if dir == "" {
118			return nil, invalidf("data directory must not be empty")
119		}
120		if err := os.MkdirAll(dir, 0o755); err != nil {
121			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
122		}
123		lockPath := filepath.Join(dir, dirLockFile)
124		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
125		if err != nil {
126			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
127		}
128		// Serialize against other processes while we read / validate.
129		if err := lockExclusive(lock); err != nil {
130			lock.Close()
131			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
132		}
133	
134		s := &Store{dir: dir, lock: lock}
135		if err := s.loadLocked(); err != nil {
136			unlockLock(lock)
137			lock.Close()
138			return nil, err
139		}
140		// The lock is taken again per operation; holding it for the store's
141		// lifetime would forbid two open handles on one directory.
142		if err := unlockLock(lock); err != nil {
143			lock.Close()
144			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
145		}
146		return s, nil
147	}
148	
149	// Close releases the directory lock. It does not discard committed data.
150	func (s *Store) Close() error {
151		s.mu.Lock()
152		defer s.mu.Unlock()
153		if s.lock == nil {
154			return nil
155		}
156		var first error
157		if err := unlockLock(s.lock); err != nil {
158			first = err
159		}
160		if err := s.lock.Close(); err != nil && first == nil {
161			first = err
162		}
163		s.lock = nil
164		return first
165	}
166	
167	// Dir reports the data directory backing the store.
168	func (s *Store) Dir() string { return s.dir }
169	
170	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
171	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
172	
173	// loadLocked reads and validates the committed file. Caller must hold the
174	// exclusive flock; the in-process mutex is taken by the public Open path.
175	func (s *Store) loadLocked() error {
176		raw, err := os.ReadFile(s.dataPath())
177		if errors.Is(err, os.ErrNotExist) {
178			s.data = envelope{Format: FormatVersion}
179			return nil
180		}
181		if err != nil {
182			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
183		}
184		if len(strings.TrimSpace(string(raw))) == 0 {
185			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
186		}
187	
188		var env envelope
189		if err := json.Unmarshal(raw, &env); err != nil {
190			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
191		}
192		if env.Format == 0 {
193			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
194		}
195		if env.Format != FormatVersion {
196			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
197				s.dataPath(), env.Format, FormatVersion)
198		}
199		if err := validateEnvelope(env); err != nil {
200			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
201		}
202		s.data = env
203		return nil
204	}
205	
206	// commitLocked writes the pending state atomically: temp file → fsync →
207	// rename → fsync directory. Caller must hold both the in-process mutex and
208	// the exclusive flock; all in-memory mutations must already have happened and
209	// been rule-checked, so a failure here occurs before any success is reported.
210	func (s *Store) commitLocked() error {
211		s.data.Format = FormatVersion
212		// Stable output: records are stored sorted so files are deterministic.
213		sortEnvelope(&s.data)
214	
215		payload, err := json.MarshalIndent(&s.data, "", "  ")
216		if err != nil {
217			return fmt.Errorf("cannot encode data: %w", err)
218		}
219		payload = append(payload, '\n')
220	
221		tmp := s.tmpPath()
222		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
223		if err != nil {
224			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
225		}
226		if _, err := f.Write(payload); err != nil {
227			f.Close()
228			os.Remove(tmp)
229			return fmt.Errorf("cannot write staged data: %w", err)
230		}
231		if err := f.Sync(); err != nil {
232			f.Close()
233			os.Remove(tmp)
234			return fmt.Errorf("cannot flush staged data: %w", err)
235		}
236		if err := f.Close(); err != nil {
237			os.Remove(tmp)
238			return fmt.Errorf("cannot finish staged data: %w", err)
239		}
240		if err := os.Rename(tmp, s.dataPath()); err != nil {
241			os.Remove(tmp)
242			return fmt.Errorf("cannot commit data file: %w", err)
243		}
244		if err := syncDir(s.dir); err != nil {
245			// The rename already happened; lack of dir fsync only weakens crash
246			// durability, never correctness of what is visible now.
247			return nil
248		}
249		return nil
250	}
251	
252	// withLock runs fn under the in-process mutex and an exclusive flock, then
253	// atomically commits when fn requests it. The on-disk state is re-read after
254	// acquiring the lock, so concurrent commits from another process or another
255	// handle are always observed. Operations validate before mutating; a rejected
256	// operation (commit=false or an error) writes nothing and leaves committed
257	// state unchanged.
258	func (s *Store) withLock(fn func() (commit bool, err error)) error {
259		s.mu.Lock()
260		defer s.mu.Unlock()
261		if s.lock == nil {
262			return invalidf("store is closed")
263		}
264		if err := lockExclusive(s.lock); err != nil {
265			return fmt.Errorf("cannot lock data directory: %w", err)
266		}
267		defer unlockLock(s.lock)
268	
269		if err := s.loadLocked(); err != nil {
270			return err
271		}
272		commit, err := fn()
273		if err != nil {
274			return err
275		}
276		if !commit {
277			return nil
278		}
279		return s.commitLocked()
280	}
281	
282	// withLockRead runs fn under a shared flock over freshly reloaded state.
283	func (s *Store) withLockRead(fn func() error) error {
284		s.mu.Lock()
285		defer s.mu.Unlock()
286		if s.lock == nil {
287			return invalidf("store is closed")
288		}
289		if err := lockShared(s.lock); err != nil {
290			return fmt.Errorf("cannot lock data directory: %w", err)
291		}
292		defer unlockLock(s.lock)
293		if err := s.loadLocked(); err != nil {
294			return err
295		}
296		return fn()
297	}
298	
299	func sortEnvelope(env *envelope) {
300		sort.Slice(env.Circuits, func(i, j int) bool {
301			if env.Circuits[i].Name != env.Circuits[j].Name {
302				return env.Circuits[i].Name < env.Circuits[j].Name
303			}
304			return env.Circuits[i].Version < env.Circuits[j].Version
305		})
306		sort.Slice(env.Setups, func(i, j int) bool {
307			if env.Setups[i].Name != env.Setups[j].Name {
308				return env.Setups[i].Name < env.Setups[j].Name
309			}
310			return env.Setups[i].Version < env.Setups[j].Version
311		})
312		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
313		sort.Slice(env.Artifacts, func(i, j int) bool {
314			if env.Artifacts[i].Name != env.Artifacts[j].Name {
315				return env.Artifacts[i].Name < env.Artifacts[j].Name
316			}
317			return env.Artifacts[i].Version < env.Artifacts[j].Version
318		})
319	}
320	
321	// validateEnvelope re-checks every invariant on load so a tampered or
322	// hand-edited file cannot bypass the domain rules.
323	func validateEnvelope(env envelope) error {
324		seenCircuit := make(map[[2]string]bool)
325		circuitOK := make(map[[2]string]bool)
326		for i, c := range env.Circuits {
327			key := [2]string{c.Name, itoa(c.Version)}
328			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
329				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
330			}
331			if c.Version <= 0 {
332				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
333			}
334			if seenCircuit[key] {
335				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
336			}
337			seenCircuit[key] = true
338			if c.Constraints <= 0 {
339				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
340			}
341			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
342				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
343			}
344			if c.Definition != nil {
345				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
346					return err
347				}
348			}
349			circuitOK[key] = true
350		}
351		seenSetup := make(map[[2]string]bool)
352		for i, p := range env.Setups {
353			key := [2]string{p.Name, itoa(p.Version)}
354			if !circuitOK[key] {
355				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
356			}
357			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
358			if c == nil || !c.Frozen {
359				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
360			}
361			if seenSetup[key] {
362				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
363			}
364			seenSetup[key] = true
365		}
366		seenJob := make(map[string]bool)
367		for i, j := range env.Jobs {
368			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
369				return fmt.Errorf("job #%d has an empty or blank id", i+1)
370			}
371			if seenJob[j.ID] {
372				return fmt.Errorf("job %q appears more than once", j.ID)
373			}
374			seenJob[j.ID] = true
375			if j.Kind != "prove" {
376				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
377			}
378			if j.Attempt <= 0 {
379				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
380			}
381			key := [2]string{j.Circuit, itoa(j.Version)}
382			if !circuitOK[key] {
383				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
384			}
385			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
386			if c == nil || !c.Frozen {
387				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
388			}
389			if !seenSetup[key] {
390				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
391			}
392		}
393		seenArtifact := make(map[[2]string]bool)
394		for i, a := range env.Artifacts {
395			key := [2]string{a.Name, itoa(a.Version)}
396			if !circuitOK[key] {
397				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
398			}
399			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
400			if c == nil || !c.Frozen {
401				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
402			}
403			if seenArtifact[key] {
404				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
405			}
406			seenArtifact[key] = true
407			if c.Definition == nil {
408				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
409			}
410			if a.Constraints != c.Constraints {
411				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
412					a.Name, a.Version, a.Constraints, c.Constraints)
413			}
414			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
415			if err != nil {
416				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
417			}
418			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
419				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
420			}
421			wantHash := artifactHash(a.Name, a.Version, def)
422			if a.Hash != wantHash {
423				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
424					a.Name, a.Version, a.Hash, wantHash)
425			}
426		}
427		return nil
428	}
429	
430	// validatePersistDefinition re-validates a stored definition against its
431	// version's declared counts: prime modulus, in-range wires and an exact
432	// constraint count match.
433	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
434		parsed, err := definitionFromPersist(*def, public, private)
435		if err != nil {
436			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
437		}
438		if !parsed.compatibleWith(constraints, public, private) {
439			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
440		}
441		return nil
442	}
443	
444	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
445		for i := range cs {
446			if cs[i].Name == name && cs[i].Version == version {
447				return &cs[i]
448			}
449		}
450		return nil
451	}
452	
453	func itoa(v int) string { return fmt.Sprintf("%d", v) }
454

