1	package main
2	
3	import (
4		"errors"
5		"flag"
6		"fmt"
7		"os"
8	
9		"github.com/asdhoaiqqq/zkcircuit-workbench/zkcircuit"
10	)
11	
12	// Process exit codes for the data commands.
13	const (
14		exitOK    = 0
15		exitRule  = 1 // business rule failure (not found, conflict, frozen, …)
16		exitUsage = 2 // bad command line
17		exitData  = 3 // storage cannot be read safely (corrupt/truncated/bad format)
18	)
19	
20	// dataCommands is the set of commands backed by a persistent data directory.
21	var dataCommands = map[string]bool{
22		"circuit-create":    true,
23		"circuit-update":    true,
24		"circuit-freeze":    true,
25		"circuit-get":       true,
26		"circuit-list":      true,
27		"setup-record":      true,
28		"setup-get":         true,
29		"job-submit":        true,
30		"job-get":           true,
31		"job-list":          true,
32		"constraint-import": true,
33		"circuit-compile":   true,
34		"input-check":       true,
35	}
36	
37	// dispatchDataCommand runs cmd with args. handled is false when cmd is not a
38	// data command, so the caller keeps the historical "unknown command" path.
39	func dispatchDataCommand(cmd string, args []string) (code int, handled bool) {
40		if !dataCommands[cmd] {
41			return exitUsage, false
42		}
43		return runDataCommand(cmd, args), true
44	}
45	
46	func runDataCommand(cmd string, args []string) int {
47		fs, f := newFlagSet(cmd, os.Stderr)
48		if err := fs.Parse(args); err != nil {
49			return exitUsage
50		}
51		// Record which value flags were explicitly provided, so circuit-update
52		// can distinguish "omitted" from "given a default value".
53		fs.Visit(func(fl *flag.Flag) {
54			switch fl.Name {
55			case "constraints":
56				f.constraintsSet = true
57			case "public-inputs":
58				f.publicInSet = true
59			case "private-inputs":
60				f.privateInSet = true
61			case "description":
62				f.descriptionSet = true
63			}
64		})
65		if len(fs.Args()) > 0 {
66			fmt.Fprintf(os.Stderr, "error: %s does not accept positional arguments (got %q)\n", cmd, fs.Args()[0])
67			return exitUsage
68		}
69		if f.dir == "" {
70			fmt.Fprintf(os.Stderr, "error: --dir is required for %s\n", cmd)
71			return exitUsage
72		}
73	
74		switch cmd {
75		case "circuit-create":
76			return cmdCircuitCreate(f)
77		case "circuit-update":
78			return cmdCircuitUpdate(f)
79		case "circuit-freeze":
80			return cmdCircuitFreeze(f)
81		case "circuit-get":
82			return cmdCircuitGet(f)
83		case "circuit-list":
84			return cmdCircuitList(f)
85		case "setup-record":
86			return cmdSetupRecord(f)
87		case "setup-get":
88			return cmdSetupGet(f)
89		case "job-submit":
90			return cmdJobSubmit(f)
91		case "job-get":
92			return cmdJobGet(f)
93		case "job-list":
94			return cmdJobList(f)
95		case "constraint-import":
96			return cmdConstraintImport(f)
97		case "circuit-compile":
98			return cmdCircuitCompile(f)
99		case "input-check":
100			return cmdInputCheck(f)
101		}
102		return exitUsage
103	}
104	
105	func requireNameVersion(cmd string, f *cliFlags) (bool, int) {
106		if f.name == "" {
107			fmt.Fprintf(os.Stderr, "error: --name is required for %s\n", cmd)
108			return false, exitUsage
109		}
110		if f.version <= 0 {
111			fmt.Fprintf(os.Stderr, "error: --version must be a positive integer for %s\n", cmd)
112			return false, exitUsage
113		}
114		return true, exitOK
115	}
116	
117	func openStore(f *cliFlags) (*zkcircuit.Store, int) {
118		store, err := zkcircuit.Open(f.dir)
119		if err != nil {
120			return nil, reportStoreError(err)
121		}
122		return store, exitOK
123	}
124	
125	// reportStoreError prints a failed storage/domain call and returns the exit
126	// code. Rule failures are 1; unreadable data is 3.
127	func reportStoreError(err error) int {
128		if errors.Is(err, zkcircuit.ErrDataCorrupt) {
129			fmt.Fprintf(os.Stderr, "error: read failed: %v\n", err)
130			return exitData
131		}
132		var domainErr zkcircuit.StoreError
133		if errors.As(err, &domainErr) {
134			fmt.Fprintf(os.Stderr, "error: %v\n", err)
135			return exitRule
136		}
137		fmt.Fprintf(os.Stderr, "error: storage failure: %v\n", err)
138		return exitData
139	}
140	
141	func circuitFromFlags(f *cliFlags) zkcircuit.Circuit {
142		return zkcircuit.Circuit{
143			Name: f.name, Version: f.version,
144			Constraints: f.constraints, PublicInputs: f.publicIn, PrivateInputs: f.privateIn,
145			Description: f.description,
146		}
147	}
148	
149	func formatCircuit(c zkcircuit.Circuit) string {
150		return fmt.Sprintf("name=%s version=%d constraints=%d public_inputs=%d private_inputs=%d frozen=%t description=%q",
151			c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Frozen, c.Description)
152	}
153	
154	func formatJob(j zkcircuit.Job) string {
155		s := fmt.Sprintf("id=%s circuit=%s version=%d kind=%s attempt=%d", j.ID, j.Circuit, j.Version, j.Kind, j.Attempt)
156		if j.Artifact != "" {
157			s += " artifact=" + fmt.Sprintf("%q", j.Artifact)
158		}
159		return s
160	}
161	
162	func cmdCircuitCreate(f *cliFlags) int {
163		if ok, code := requireNameVersion("circuit-create", f); !ok {
164			return code
165		}
166		store, code := openStore(f)
167		if store == nil {
168			return code
169		}
170		defer store.Close()
171	
172		c, err := store.CreateCircuit(circuitFromFlags(f))
173		if err != nil {
174			return reportStoreError(err)
175		}
176		fmt.Println("circuit version:", formatCircuit(c))
177		return exitOK
178	}
179	
180	func cmdCircuitUpdate(f *cliFlags) int {
181		if ok, code := requireNameVersion("circuit-update", f); !ok {
182			return code
183		}
184		store, code := openStore(f)
185		if store == nil {
186			return code
187		}
188		defer store.Close()
189	
190		// Only explicitly provided fields are changed; omitted fields keep their
191		// stored values. A non-nil pointer — even to zero or the empty string —
192		// replaces the field.
193		patch := zkcircuit.PartialCircuit{}
194		if f.constraintsSet {
195			patch.Constraints = &f.constraints
196		}
197		if f.publicInSet {
198			patch.PublicInputs = &f.publicIn
199		}
200		if f.privateInSet {
201			patch.PrivateInputs = &f.privateIn
202		}
203		if f.descriptionSet {
204			patch.Description = &f.description
205		}
206	
207		c, err := store.UpdateCircuitPartial(f.name, f.version, patch)
208		if err != nil {
209			return reportStoreError(err)
210		}
211		fmt.Println("circuit updated:", formatCircuit(c))
212		return exitOK
213	}
214	
215	func cmdCircuitFreeze(f *cliFlags) int {
216		if ok, code := requireNameVersion("circuit-freeze", f); !ok {
217			return code
218		}
219		store, code := openStore(f)
220		if store == nil {
221			return code
222		}
223		defer store.Close()
224	
225		c, err := store.FreezeCircuit(f.name, f.version)
226		if err != nil {
227			return reportStoreError(err)
228		}
229		fmt.Println("circuit frozen:", formatCircuit(c))
230		return exitOK
231	}
