233	func cmdCircuitGet(f *cliFlags) int {
234		if ok, code := requireNameVersion("circuit-get", f); !ok {
235			return code
236		}
237		store, code := openStore(f)
238		if store == nil {
239			return code
240		}
241		defer store.Close()
242	
243		c, err := store.GetCircuit(f.name, f.version)
244		if err != nil {
245			return reportStoreError(err)
246		}
247		fmt.Println("circuit:", formatCircuit(c))
248		return exitOK
249	}
