251	func cmdCircuitList(f *cliFlags) int {
252		store, code := openStore(f)
253		if store == nil {
254			return code
255		}
256		defer store.Close()
257	
258		circuits, err := store.ListCircuits()
259		if err != nil {
260			return reportStoreError(err)
261		}
262		for _, c := range circuits {
263			fmt.Println("circuit:", formatCircuit(c))
264		}
265		return exitOK
266	}
267	
268	func cmdSetupRecord(f *cliFlags) int {
269		if ok, code := requireNameVersion("setup-record", f); !ok {
270			return code
271		}
272		store, c := openStore(f)
273		if store == nil {
274			return c
275		}
276		defer store.Close()
277	
278		setup, err := store.RecordSetup(f.name, f.version)
279		if err != nil {
280			return reportStoreError(err)
281		}
282		fmt.Printf("trusted setup: name=%s version=%d\n", setup.Name, setup.Version)
283		return exitOK
284	}
285	
286	func cmdSetupGet(f *cliFlags) int {
287		if ok, code := requireNameVersion("setup-get", f); !ok {
288			return code
289		}
290		store, c := openStore(f)
291		if store == nil {
292			return c
293		}
294		defer store.Close()
295	
296		setup, found, err := store.GetSetup(f.name, f.version)
