package main

import (
	"errors"
	"testing"

	"github.com/asdhoaiqqq/zkcircuit-workbench/zkcircuit"
)

func TestAPI(t *testing.T) {
	s, err := zkcircuit.Open(t.TempDir())
	if err != nil { t.Fatal(err) }
	defer s.Close()
	if _, err := s.CreateCircuit(zkcircuit.Circuit{Name: "c", Version: 1, Constraints: 1}); err != nil { t.Fatal(err) }
	if _, err := s.FreezeCircuit("c", 1); err != nil { t.Fatal(err) }
	if _, err := s.RecordSetup("c", 1); err != nil { t.Fatal(err) }

	// no artifact yet -> ErrArtifactMissing
	_, err = s.SubmitJob(zkcircuit.Job{ID: "a", Circuit: "c", Version: 1, Kind: "prove", Attempt: 1, CompiledHash: "x"})
	if !errors.Is(err, zkcircuit.ErrArtifactMissing) { t.Fatalf("want ErrArtifactMissing, got %v", err) }
	if errors.Is(err, zkcircuit.ErrArtifactMismatch) { t.Fatal("kinds not distinguishable") }

	// unbound job with legacy Artifact field round-trips
	j, err := s.SubmitJob(zkcircuit.Job{ID: "b", Circuit: "c", Version: 1, Kind: "prove", Attempt: 1, Artifact: "legacy"})
	if err != nil { t.Fatal(err) }
	if j.Artifact != "legacy" || j.CompiledHash != "" { t.Fatalf("bad round trip: %+v", j) }
	got, err := s.GetJob("b")
	if err != nil || got.Artifact != "legacy" || got.CompiledHash != "" { t.Fatalf("get: %+v %v", got, err) }
}
EOF
